insert into public.articles (id, title, excerpt, body, cover, published, regions) values ('demo-m-golan-water', 'חמישה מסלולי מים בצפון שאפשר לעשות גם עם ילדים', 'בניאס, תל דן, נחל עמוד ועוד: מסלולים קצרים עם מים זורמים, צל ונקודות טבילה, ומה כדאי לדעת לפני שיוצאים.', '## שמורת נחל חרמון (בניאס)
insert into public.articles (id, title, excerpt, body, cover, published, regions) values ('demo-m-ramon-night', 'לילה במכתש: איך לראות כוכבים כמו שצריך', 'מצפה רמון היא אחד המקומות החשוכים בארץ. מתי להגיע, מה להביא ואיפה לעמוד כדי לראות את שביל החלב.', '## מתי להגיע
insert into public.articles (id, title, excerpt, body, cover, published, regions) values ('demo-m-deadsea-sunrise', 'זריחה במצדה וטבילה בים המלח: תוכנית לבוקר אחד', 'עולים בשביל הנחש לפני הזריחה, יורדים לארוחת בוקר, ומסיימים בציפה במים. כל מה שצריך לדעת.', '## לפני הזריחה
